# ------------------------------------------------------------------
# MEDICINE ALARM POLLING ENGINE (runs on every page)
# ------------------------------------------------------------------
# Existing reminder/database logic is preserved. Only the browser playback
# mechanism is changed to use Streamlit's native audio element.


def _load_alarm_audio():
    """
    Embedded CareAI medication alarm sound.
    The MP3 is embedded directly in the source file so the alarm sound
    does not depend on a separate asset file being present at runtime.
    """
    alarm_mp3_base64 = """"""
    return base64.b64decode(alarm_mp3_base64)


ALARM_AUDIO_BYTES = _load_alarm_audio()

# The uploaded clinical alarm sound is played automatically when a reminder is due.
# There is no manual test button and no visible audio player.


@st.fragment(run_every=5)
def medicine_alarm_polling_engine():
    ist_timezone = pytz.timezone('Asia/Kolkata')
    current_ist_time = datetime.now(ist_timezone)
    current_time_str = current_ist_time.strftime('%H:%M')

    with db.get_db_connection() as conn:
        active_meds = conn.execute(
            "SELECT medication_name, dosage, reminder_time FROM medications WHERE is_active = 1"
        ).fetchall()

    for med in active_meds:
        if med['reminder_time'] == current_time_str:
            reminder_key = f"{med['medication_name']}_{current_time_str}"

            if st.session_state.last_triggered_reminder != reminder_key:
                st.session_state.last_triggered_reminder = reminder_key

                st.markdown(f"""
                    <div class="alarm-banner">
                        <b>🚨 LIVE REMINDER ALARM: {current_time_str}</b><br>
                        Time to take your {med['medication_name']} (Dosage: {med['dosage']}).
                    </div>
                """, unsafe_allow_html=True)

                # Keep Streamlit's native audio playback because it is the
                # mechanism currently producing the working alarm sound.
                # CSS hides the player completely; only the sound is emitted.
                st.audio(ALARM_AUDIO_BYTES, format="audio/mpeg", autoplay=True)

                # Existing browser notification behavior is retained.
                st.components.v1.html(
                    f"""
                    <script>
                    (() => {{
                        if (window.Notification && Notification.permission !== "denied") {{
                            const showNotification = () => {{
                                try {{
                                    new Notification("💊 CareAI Medication Alarm", {{
                                        body: "It is {current_time_str}! Take your {med['medication_name']} ({med['dosage']}).",
                                        icon: "https://cdn-icons-png.flaticon.com/512/822/822143.png",
                                        silent: false,
                                        requireInteraction: true
                                    }});
                                }} catch (e) {{}}
                            }};

                            if (Notification.permission === "granted") {{
                                showNotification();
                            }} else {{
                                Notification.requestPermission().then(permission => {{
                                    if (permission === "granted") showNotification();
                                }}).catch(() => {{}});
                            }}
                        }}
                    }})();
                    </script>
                    """,
                    height=0,
                )


medicine_alarm_polling_engine()


