def render_floating_chat_widget():
    if not st.session_state.chat_open:
        # ---- Collapsed state: floating pill button only ----
        with st.container(key="chat_toggle_wrap"):
            if st.button("👨‍⚕️", key="chat_toggle_btn", help="Open Dr. CareAI clinical assistant"):
                st.session_state.chat_open = True
                st.rerun()
        return

    # ---- Expanded state: full glass chat panel, toggle button is gone ----
    with st.container(key="chat_panel_wrap"):
        title_col, close_col = st.columns([6, 1])
        with title_col:
            st.markdown(
                '<div class="chat-widget-title">🩺 Live Clinical AI Agent</div>',
                unsafe_allow_html=True,
            )
        with close_col:
            with st.container(key="chat_close_col"):
                if st.button("✕", key="chat_close_btn"):
                    st.session_state.chat_open = False
                    st.rerun()

        chat_box = st.container(height=480, key="chat_scroll_box")
        with chat_box:
            if not st.session_state.chat_history:
                st.caption("Ask a clinical question to get started.")
            for role, text in st.session_state.chat_history:
                with st.chat_message(role):
                    st.write(text)

        if user_query := st.chat_input("Query clinical definitions or insights...", key="floating_chat_input"):
            st.session_state.chat_history.append(("user", user_query))

            with chat_box:
                with st.chat_message("user"):
                    st.write(user_query)
                with st.chat_message("assistant"):
                    with st.spinner("Processing..."):
                        context_history = st.session_state.chat_history[-4:]
                        ai_response = st.session_state.agent.respond(context_history, user_query)
                        st.write(ai_response)

            st.session_state.chat_history.append(("assistant", ai_response))

        if st.session_state.chat_history:
            if st.button("Clear conversation", key="floating_chat_clear", use_container_width=True):
                st.session_state.chat_history = []
                st.rerun()


